(function(){try{var e=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},p=new e.Error().stack;p&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[p]="83c1d5ee-0c06-4f83-8e92-3ad3aaaafd51",e._sentryDebugIdIdentifier="sentry-dbid-83c1d5ee-0c06-4f83-8e92-3ad3aaaafd51")}catch{}})();var a="社群行為守則",d={p1:"我們都熱愛音樂！與任何社群一樣，我們訂有一套行為守則，以維持和諧與良好氛圍，並確保大家在此感到安心自在。讓我們共同營造一個友善而能啟發創作的環境。"},r={p1:"相處原則：",p2:"尊重",p3:"夥伴精神",p4:"公平"},s={p1:"期望的行為：",p2:"尊重每一位成員。",p3:"歡迎具建設性的意見。",p4:"這裡以音樂為本，請只發佈與音樂相關的留言與內容。",p5:"以你希望被對待的方式對待他人。"},t={p1:"不可接受的行為（我們可不作事前通知而刪除你的帳戶）：",p2:"以不敬或帶有冒犯性的方式對待其他創作者。",p3:"垃圾訊息。",p4:"分享色情內容。",p5:"發表有意貶低、冒犯或滋擾任何社群成員的留言。"},f={p1:"公開措施："},n={p1:"會被即時封鎖的原因：",p2:"分享任何形式的色情內容（圖片、留言等）。",p3:"分享內容或發表言論，鼓吹或煽動暴力、種族主義、排外、恐同、性別歧視等。",p4:"向他人濫發訊息。"},o={p1:"其他不可接受的行為：",p2:"侮辱或發佈貶損社群內任何成員的留言：",p3:"第一次：我們會停用你的留言功能，直至另行通知。",p4:"第二次：我們將永久停用你的留言功能，或刪除你的帳戶。",p5:"向支援團隊濫發訊息：",p6:"只要你以尊重的態度，並僅就本平台事宜聯絡我們，我們的支援團隊一向樂意協助。任何不敬或帶有濫發性質的行為概不接受，並可能導致你的帳戶被刪除。"},i={p1:"何謂不敬的留言？",p2:"此類留言通常與主題無關、不恰當、有害，或只是惹人厭煩。發言者並非出於善意，意圖令對方感到難受或受羞辱。",p3:"如你不確定自己的留言是否不敬，請避免發佈，並以尊重、文明的方式表達自己。"},u={title:a,s1:d,s2:r,s3:s,s4:t,s5:f,s6:n,s7:o,s8:i};export{u as default,d as s1,r as s2,s as s3,t as s4,f as s5,n as s6,o as s7,i as s8,a as title};

